class Layer2Cos(TextualConvention, Integer32):
    reference = 'IEEE 802.1D, 2004 Edition, Annex G User priorities and traffic\n            classes.'
    description = 'An integer that is in the range of the layer 2 CoS values. It\n        corresponds to the IEEE 802.1P CoS value which defines eight\n        (2^3) user priority levels.\n        Note: the IEEE 802.1P has been merged into IEEE 802.1D.'
    status = 'current'
    subtypeSpec = Integer32.subtypeSpec + ValueRangeConstraint(0, 7)

