class CiscoNetworkAddress(TextualConvention, OctetString):
    description = 'Represents a network layer address.  The length and format of\n        the address is protocol dependent as follows:\n        ip        4 octets\n        decnet    2 octets\n        pup       obsolete\n        chaos     2 octets\n        xns       10 octets\n                  first 4 octets are the net number\n                  last 6 octets are the host number\n        x121    \n        appletalk 3 octets\n                  first 2 octets are the net number\n                  last octet is the host number\n        clns\n        lat\n        vines     6 octets\n                  first 4 octets are the net number\n                  last 2 octets are the host number\n        cons\n        apollo    10 octets\n                  first 4 octets are the net number\n                  last 6 octets are the host number\n        stun      8 octets\n        novell    10 octets\n                  first 4 octets are the net number\n                  last 6 octets are the host number\n        qllc      6 octets\n        bstun     1 octet - bi-sync serial tunnel \n        snapshot  1 octet\n        atmIlmi   4 octets\n        x25 pvc   2 octets (12 bits)\n        ipv6      16 octets\n        cdm\n        nbf\n        bgpIgx\n        clnsPfx  upto 20 octets\n        http     upto 70 octets\n                 first 4 octets are the IPv4 host \n                 address\n                 next 2 octets are the TCP port \n                 number\n                 remaining(1 upto 64) octets are \n                 the URI'
    status = 'current'

